        function handlePasswordSubmit(e) {
          e.preventDefault();
          var wishesPassword = '';
          var rsvpPassword = '';
          var wishesInput = document.getElementById('hiweb-wishes-password');
          var rsvpInput = document.getElementById('hiweb-rsvp-password');
          if (wishesInput) {
            wishesPassword = wishesInput.value.trim();
          }
          if (rsvpInput) {
            rsvpPassword = rsvpInput.value.trim();
          }
          if (!wishesPassword && !rsvpPassword) {
            showError('Vui lòng nhập mật khẩu');
            return;
          }
          

          showError('Đang xác thực...');

          var slug = extractSlug();

          window.__hiwebUserPasswordSubmit = true;
          verifyPassword(slug, wishesPassword, rsvpPassword);
        }

        function extractSlug() {
          var hostname = window.location.hostname;

          var parts = hostname.split('.');
          if (parts.length > 1) {
            var subdomain = parts[0];
            if (subdomain && subdomain !== 'www' && subdomain !== 'api') {
              return subdomain;
            }
          }

          var pathSlug = window.location.pathname.split('/').filter(function(p) { return p.trim(); }).pop();
          if (pathSlug) {
            return pathSlug;
          }

          return '';
        }

      function removeLabel(input) {
  if (!input) return;

  // đi lên 2 cấp: input -> div -> wrapper
  var wrapper = input.parentElement?.parentElement;
  if (!wrapper) return;

  var label = wrapper.querySelector('label');
  if (label) {
    label.remove();
  }
}
        function autoVerifyFromSession() {
          if (hasAutoVerified) return;
          hasAutoVerified = true;

          var slug = extractSlug();

          var savedWishes = sessionStorage.getItem('invitation_' + slug + '_wishes');
          var savedRsvp = sessionStorage.getItem('invitation_' + slug + '_rsvp');

          if (!savedWishes && !savedRsvp) return;
          if (!savedWishes) savedWishes = '';
          if (!savedRsvp) savedRsvp = '';

          verifyPassword(slug, savedWishes, savedRsvp);
        }
      function verifyPassword(slug, wishesPassword, rsvpPassword) {
       var apiUrl = 'https://api.hiweb.vn/api/v1/wedding/invitation';
       var params = new URLSearchParams();
      
       var savedWishes = sessionStorage.getItem('invitation_' + slug + '_wishes');
       var savedRsvp = sessionStorage.getItem('invitation_' + slug + '_rsvp');
      
       var finalWishes = wishesPassword || savedWishes;
       var finalRsvp = rsvpPassword || savedRsvp;
      
       params.append('slug', slug);
      
       if (finalWishes) params.append('passwordWishes', finalWishes);
       if (finalRsvp) params.append('passwordRsvp', finalRsvp);
      
       var fullUrl = apiUrl + '?' + params.toString();


        fetch(fullUrl)
          .then(function (response) {
            return response.json();
          })
         .then(function (data) {

          var invitation = data?.data?.invitation;
              
          if (!invitation) {
            throw new Error("Invalid response");
          }
              
          var hasWishesArray = Array.isArray(invitation.wishes) ||
                               Array.isArray(data?.data?.wishes);
          var hasRsvpsArray = Array.isArray(invitation.rsvps) ||
                              Array.isArray(data?.data?.rsvps);

          var wishesLocked;
          if (typeof invitation.wishes_locked === 'boolean') {
            wishesLocked = invitation.wishes_locked;
          } else if (hasWishesArray) {
            wishesLocked = false;
          } else {
            var wv = invitation.wishes_visibility || invitation.wishesVisibility;
            wishesLocked = String(wv || '').toLowerCase() === 'password';
          }

          var rsvpsLocked;
          if (typeof invitation.rsvps_locked === 'boolean') {
            rsvpsLocked = invitation.rsvps_locked;
          } else if (typeof invitation.rsvp_locked === 'boolean') {
            rsvpsLocked = invitation.rsvp_locked;
          } else if (hasRsvpsArray) {
            rsvpsLocked = false;
          } else {
            var rv = invitation.rsvp_visibility || invitation.rsvps_visibility ||
                    invitation.rsvpVisibility || invitation.rsvpsVisibility;
            rsvpsLocked = String(rv || '').toLowerCase() === 'password';
          }

          currentLockState.wishesLocked = wishesLocked;
          currentLockState.rsvpsLocked = rsvpsLocked;

          if (!wishesLocked && !rsvpsLocked) {
            setTimeout(function() {
              var lockContainer = document.getElementById('hiweb-lock-container');
              
              if (lockContainer) {
                lockContainer.style.display = 'none';
              }
            }, 50);
          }
              
          var wishesInput = document.getElementById('hiweb-wishes-password');
          var rsvpInput = document.getElementById('hiweb-rsvp-password');

          var hasWishesPassword = !!wishesPassword && wishesPassword.trim() !== '';
          var hasRsvpPassword = !!rsvpPassword && rsvpPassword.trim() !== '';

          // Hide input fields that are already unlocked from previous verifications
          if (!wishesLocked && wishesInput) {
            removeLabel(wishesInput);
            var wishesWrapper = wishesInput.parentElement;
            if (wishesWrapper) {
              wishesWrapper.style.display = 'none';
            }
          }

          if (!rsvpsLocked && rsvpInput) {
            var rsvpWrapper = rsvpInput.parentElement;
            if (rsvpWrapper) {
              rsvpWrapper.style.display = 'none';
            }
          }
          
          if (!wishesLocked && hasWishesPassword) {
            sessionStorage.setItem(
              'invitation_' + slug + '_wishes',
              wishesPassword
            );
          }
              
          if (!rsvpsLocked && hasRsvpPassword) {
            sessionStorage.setItem(
              'invitation_' + slug + '_rsvp',
              rsvpPassword
            );
          }
          
          if (!wishesLocked) {
            var wishesWrapper = wishesInput?.parentElement;
            if (wishesWrapper) {
              wishesWrapper.style.display = 'none';
            }
          }

          if (!rsvpsLocked) {
            var rsvpWrapper = rsvpInput?.parentElement;
            if (rsvpWrapper) {
              rsvpWrapper.style.display = 'none';
            }
          }
          
          if (hasWishesPassword && hasRsvpPassword && wishesLocked && rsvpsLocked) {
            showError('Mật khẩu lời chúc và RSVP không đúng!');
            return;
          }

          if (hasWishesPassword && wishesLocked) {
            showError('Mật khẩu lời chúc không đúng!');
            return;
          }

          if (hasRsvpPassword && rsvpsLocked) {
            showError('Mật khẩu RSVP không đúng!');
            return;
          }
          
          var shouldClose = false;
          
          if (hasWishesPassword && !wishesLocked) {
            shouldClose = true;
          }
          
          if (hasRsvpPassword && !rsvpsLocked) {
            shouldClose = true;
          }
          
          if (!wishesLocked && !rsvpsLocked) {
            shouldClose = true;
          }
          
          if (shouldClose) {
            try {
              closePasswordModal();
            } catch (error) {
              console.error('❌ Error closing password modal:', error);
            }
          }

          if (window.__hiwebUserPasswordSubmit && shouldClose) {
            window.__hiwebUserPasswordSubmit = false;
            window.location.reload();
            return;
          }

          if (!wishesLocked && !rsvpsLocked) {
            var lockContainer = document.getElementById('hiweb-lock-container');
            if (lockContainer) {
              try {
                lockContainer.style.display = 'none';
              } catch (error) {
                console.error('❌ Error hiding lock container:', error);
              }
            } else {
              console.warn('⚠️ Lock container not found in DOM');
            }
          }
              
        })
          .catch(function (error) {
            showError('Có lỗi xảy ra, thử lại!');
          });
        }
        function togglePasswordVisibility(input, toggleBtn) {
          var svgHTML;
          if (input.type === 'password') {
            input.type = 'text';
            svgHTML = '<svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path><line x1="1" y1="1" x2="23" y2="23"></line></svg>';
          } else {
            input.type = 'password';
            svgHTML = '<svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path><circle cx="12" cy="12" r="3"></circle></svg>';
          }
          toggleBtn.innerHTML = svgHTML;
        }

        function showError(message) {
          if (errorEl) {
            errorEl.textContent = message;
            errorEl.style.display = 'block';
          }
        }

       if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
    initLockButton();
    autoVerifyFromSession(); 
   });
} else {
  initLockButton();
  autoVerifyFromSession(); 
}
